import io,base64,tarfile,os,sys,subprocess,time,json
os.chdir("/kaggle/working"); tarfile.open(fileobj=io.BytesIO(base64.b64decode("")),mode="r:gz").extractall(".")
sys.path.insert(0,"/kaggle/working")
import numpy as np, cupy as cp
from genesis import genome as GN, town, town_xp
print("device", cp.cuda.runtime.getDeviceProperties(0)["name"])
sys.path.insert(0,"/kaggle/working/tests"); import fakecupy
KEYS=["births","survival","honesty","bond","cheat_births","cheat_survival"]
def perm_p(x,y,n=10000,rng=np.random.default_rng(0)):
    x,y=np.asarray(x),np.asarray(y); o=abs(x.mean()-y.mean()); z=np.concatenate([x,y]); c=0
    for _ in range(n): rng.shuffle(z); c+=abs(z[:len(x)].mean()-z[len(x):].mean())>=o
    return (c+1)/(n+1)
N=96; res={}
for name,env in [("cheaters0.1",dict(town.default_env(),cheaters=0.1)),("default",town.default_env())]:
    R={arm:{k:[] for k in KEYS} for arm in ("numpy","cupy","fake")}
    for s in range(N):
        g=GN.sample(np.random.default_rng(1000+s),64)
        outs=dict(numpy=town.run_town(g,env,s,T=96,per_genome=4),cupy=town_xp.run_town(g,env,s,T=96,per_genome=4,xp=cp),
                  fake=town_xp.run_town(g,env,s,T=96,per_genome=4,xp=fakecupy.cp))
        for arm,o in outs.items():
            for k in KEYS:
                if k in o: R[arm][k].append(float(np.nanmean(o[k])))
    for k in KEYS:
        if not R["numpy"][k]: continue
        m={a:float(np.mean(R[a][k])) for a in R}; se=float(np.std(R["numpy"][k])/np.sqrt(N))
        res[name+"/"+k]=dict(**m, se_numpy=se, p_cupy=perm_p(R["numpy"][k],R["cupy"][k]), p_fake=perm_p(R["numpy"][k],R["fake"][k]), p_cupy_vs_fake=perm_p(R["cupy"][k],R["fake"][k]))
        print(name,k,json.dumps({kk:round(v,4) for kk,v in res[name+"/"+k].items()}),flush=True)
json.dump(res,open("gpu_validation96.json","w"),indent=1)
